package com.wayrapass.service;
import com.wayrapass.dto.request.DriverRequest; import com.wayrapass.dto.response.DriverResponse; import com.wayrapass.exception.*; import com.wayrapass.model.*; import com.wayrapass.repository.*; import com.wayrapass.security.CurrentUser; import lombok.RequiredArgsConstructor; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import java.util.*;
@Service @RequiredArgsConstructor public class DriverService {
 private static final List<TripStatus> ACTIVE_TRIP_STATUSES=List.of(TripStatus.BOARDING,TripStatus.IN_PROGRESS);
 private final DriverRepository drivers; private final UserRepository users; private final TripRepository trips; private final PasswordEncoder encoder; private final CurrentUser current;
 @Transactional(readOnly=true) public List<DriverResponse> all(){return drivers.findAllByOrderByIdAsc().stream().map(this::out).toList();}
 @Transactional(readOnly=true) public DriverResponse one(Long id){return out(get(id));}
 @Transactional(readOnly=true) public DriverResponse me(){return out(drivers.findByUserId(current.id()).orElseThrow(()->new ResourceNotFoundException("Perfil de conductor no encontrado.")));}
 @Transactional public DriverResponse create(DriverRequest r){if(r.password()==null)throw new BusinessRuleException("password es obligatorio al crear un conductor.");validateState(r);if(users.existsByEmailIgnoreCase(r.email()))throw new ConflictException("El correo ya existe.");if(drivers.existsByLicenseNumberIgnoreCase(r.licenseNumber()))throw new ConflictException("La licencia ya existe.");User u=new User();u.setFullName(r.fullName().trim());u.setEmail(r.email().trim().toLowerCase());u.setPhone(trim(r.phone()));u.setPasswordHash(encoder.encode(r.password()));u.setRole(Role.DRIVER);u.setEnabled(r.operationalStatus()!=DriverOperationalStatus.INACTIVE);users.save(u);Driver d=new Driver();d.setUser(u);apply(d,r);return out(drivers.save(d));}
 @Transactional public DriverResponse update(Long id,DriverRequest r){Driver d=get(id);validateState(r);if(drivers.existsByLicenseNumberIgnoreCaseAndIdNot(r.licenseNumber(),id))throw new ConflictException("La licencia ya existe.");if(users.existsByEmailIgnoreCaseAndIdNot(r.email(),d.getUser().getId()))throw new ConflictException("El correo ya existe.");apply(d,r);d.getUser().setFullName(r.fullName().trim());d.getUser().setEmail(r.email().trim().toLowerCase());d.getUser().setPhone(trim(r.phone()));d.getUser().setEnabled(r.operationalStatus()!=DriverOperationalStatus.INACTIVE);return out(d);}
 @Transactional public void delete(Long id){Driver d=get(id);if(trips.existsByDriverIdAndStatusIn(id,ACTIVE_TRIP_STATUSES))throw new BusinessRuleException("No se puede deshabilitar un conductor con un viaje operativo.");d.getUser().setEnabled(false);d.setOperationalStatus(DriverOperationalStatus.INACTIVE);}
 private Driver get(Long id){return drivers.findById(id).orElseThrow(()->new ResourceNotFoundException("Conductor no encontrado."));} private void apply(Driver d,DriverRequest r){d.setLicenseNumber(r.licenseNumber().trim().toUpperCase());d.setLicenseCategory(r.licenseCategory().trim());d.setLicenseExpiration(r.licenseExpiration());d.setCredentialImageUrl(trim(r.credentialImageUrl()));d.setAuthorizationStatus(r.authorizationStatus());d.setOperationalStatus(r.operationalStatus());}
 private void validateState(DriverRequest r){if(r.authorizationStatus()==AuthorizationStatus.AUTHORIZED&&(r.licenseExpiration()==null||r.licenseExpiration().isBefore(LocalDate.now())))throw new BusinessRuleException("No se puede autorizar un conductor sin una licencia vigente.");if(r.operationalStatus()==DriverOperationalStatus.AVAILABLE&&r.authorizationStatus()!=AuthorizationStatus.AUTHORIZED)throw new BusinessRuleException("Solo un conductor autorizado puede marcarse como disponible.");}
 private DriverResponse out(Driver d){User u=d.getUser();return new DriverResponse(d.getId(),u.getId(),u.getFullName(),u.getEmail(),u.getPhone(),d.getLicenseNumber(),d.getLicenseCategory(),d.getLicenseExpiration(),d.getCredentialImageUrl(),d.getAuthorizationStatus(),d.getOperationalStatus(),d.getCreatedAt(),d.getUpdatedAt());} private static String trim(String s){return s==null||s.isBlank()?null:s.trim();}
}
